if (attempt > maxAttempts) {
  node.status({ fill: 'green', shape: 'dot', text: `subscriptions already attempted ${maxAttempts} times` });
  return null;
}
flow.set('subscription_attempts', attempt);
const lines = ['LINE-01', 'LINE-02', 'LINE-03'];
const equipments = ['CAST-01', 'CNC-01', 'CNC-02', 'CNC-03', 'WASH-01', 'ASSY-01', 'ASSY-02', 'TEST-01', 'TEST-02'];

const processTagsByEquipment = {
  'CAST-01': [
    ['power', 'Boolean'],
    ['injection_pressure_sp', 'Double'],
    ['mold_temperature_sp', 'Double'],
    ['injection_pressure', 'Double'],
