const sensorDasTags = [
  ['vibration_rms', 'Double'],
  ['vibration_sample_rate_hz', 'Double'],
  ['vibration_window_size', 'Double'],
  ['vibration_stride', 'Double'],
  ['vibration_raw_length', 'Double'],
  ['current_a', 'Double'],
  ['voltage_v', 'Double'],
