function clean(value) { return String(value).replace(/[^A-Za-z0-9_]/g, '_'); }
function targetLineId(lineId) { return lineId.replace('-', '_'); }
function targetEquipmentId(equipmentId) { return equipmentId.replace('-', '_'); }

function makeLineTags(lineId) {
  const result = [];
  result.push({ name: `${lineId}.line_ts`, sourceNodeId: `ns=2;s=${lineId}.line_ts`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.line_ts`, datatype: 'String' });
  result.push({ name: `${lineId}.payload`, sourceNodeId: `ns=2;s=${lineId}.payload`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.payload`, datatype: 'String' });
  result.push({ name: `${lineId}.schema_version`, sourceNodeId: `ns=2;s=${lineId}.schema_version`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.schema_version`, datatype: 'String' });
  for (const equipmentId of equipments) {
    result.push({ name: `${lineId}.${equipmentId}.status`, sourceNodeId: `ns=2;s=${lineId}.${equipmentId}.status`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.${targetEquipmentId(equipmentId)}.status`, datatype: 'String' });
    result.push({ name: `${lineId}.${equipmentId}.ts`, sourceNodeId: `ns=2;s=${lineId}.${equipmentId}.ts`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.${targetEquipmentId(equipmentId)}.ts`, datatype: 'String' });
    result.push({ name: `${lineId}.${equipmentId}.quality`, sourceNodeId: `ns=2;s=${lineId}.${equipmentId}.quality`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.${targetEquipmentId(equipmentId)}.quality`, datatype: 'String' });
    const processTags = processTagsByEquipment[equipmentId] || [];
    for (const [tagName, datatype] of processTags) {
      result.push({ name: `${lineId}.${equipmentId}.data.${tagName}`, sourceNodeId: `ns=2;s=${lineId}.${equipmentId}.data.${tagName}`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.${targetEquipmentId(equipmentId)}.data.${tagName}`, datatype });
    }
  }
  return result;
}

function makeSensorDasTags() {
  const result = [];
  for (const lineId of lines) {
    for (const equipmentId of equipments) {
      const sourceLine = clean(lineId);
      const sourceEquipment = clean(equipmentId);
      for (const [tagName, datatype] of sensorDasTags) {
        result.push({ name: `${lineId}.${equipmentId}.sensor.${tagName}`, sourceNodeId: `ns=1;s=DAS_${sourceLine}_${sourceEquipment}_${tagName}`, targetNodeId: `ns=2;s=X_DAS.${targetLineId(lineId)}.${targetEquipmentId(equipmentId)}.sensor.${tagName}`, datatype });
      }
    }
  }
  return result;
}

const sources = {
  LINE1: makeLineTags('LINE-01'),
  LINE2: makeLineTags('LINE-02'),
  LINE3: makeLineTags('LINE-03'),
  SENSOR_DAS: makeSensorDasTags()
};
const outputOrder = ['LINE1', 'LINE2', 'LINE3', 'SENSOR_DAS'];
let total = 0;

for (const [sourceKey, tags] of Object.entries(sources)) {
  const bySource = {};
  for (const tag of tags) bySource[tag.sourceNodeId] = tag;
  flow.set(`${sourceKey}_TAGS_BY_SOURCE`, bySource);
  total += tags.length;
}

for (const [sourceKey, tags] of Object.entries(sources)) {
  const outputIndex = outputOrder.indexOf(sourceKey);
  for (const tag of tags) {
    const outputs = outputOrder.map(() => null);
    outputs[outputIndex] = {
      payload: interval,
      interval,
      topic: `${tag.sourceNodeId};datatype=${tag.datatype}`,
      sourceKey,
      tagName: tag.name,
      sourceNodeId: tag.sourceNodeId,
      targetNodeId: tag.targetNodeId,
      datatype: tag.datatype
    };
    node.send(outputs);
  }
}

node.status({ fill: 'blue', shape: 'dot', text: `subscriptions: ${total}, attempt ${attempt}/${maxAttempts}` });
return null;

const sourceKey = 'LINE1';
const originalTopic = String(msg.sourceNodeId || msg.topic || '');
const sourceNodeId = originalTopic.replace(/;datatype=.*$/, '');
if (!sourceNodeId.startsWith('ns=')) {
  return null;
}
const tagMap = flow.get(`${sourceKey}_TAGS_BY_SOURCE`) || {};
const tag = tagMap[sourceNodeId];

if (!tag) {
  node.status({ fill: 'yellow', shape: 'ring', text: `unmapped ${sourceNodeId}` });
  node.warn(`No backend mapping for ${sourceKey} topic: ${originalTopic}`);
  return null;
}

let value = msg.payload;
if (value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, 'value')) {
  value = value.value;
}

msg.payload = value;
msg.topic = `${tag.targetNodeId};datatype=${tag.datatype}`;
msg.xDas = {
  source: sourceKey,
  tag: tag.name,
  sourceNodeId,
  targetNodeId: tag.targetNodeId,
  datatype: tag.datatype,
  statusCode: msg.statusCode,
  sourceTimestamp: msg.sourceTimestamp,
  serverTimestamp: msg.serverTimestamp,
  receivedAt: new Date().toISOString()
};
return msg;

const sourceKey = 'LINE2';
const originalTopic = String(msg.sourceNodeId || msg.topic || '');
const sourceNodeId = originalTopic.replace(/;datatype=.*$/, '');
if (!sourceNodeId.startsWith('ns=')) {
  return null;
}
const tagMap = flow.get(`${sourceKey}_TAGS_BY_SOURCE`) || {};
const tag = tagMap[sourceNodeId];

if (!tag) {
