const sourceKey = 'SENSOR_DAS';
const originalTopic = String(msg.sourceNodeId || msg.topic || '');
const sourceNodeId = originalTopic.replace(/;datatype=.*$/, '');
if (!sourceNodeId.startsWith('ns=')) {
